namespace Quantum.MachineLearning {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Math;

    // Angle encoding of classical data
    operation AngleEncoding(features : Double[], qubits : Qubit[]) : Unit {
        for (i in 0..Length(features)-1) {
            if (i < Length(qubits)) {
                Ry(features[i], qubits[i]);
            }
        }
    }

    // Variational layer with RX, RZ rotations and CNOT entanglers
    operation VariationalLayer(params : Double[], qubits : Qubit[]) : Unit {
        let n = Length(qubits);

        // Single-qubit rotations
        for (i in 0..n-1) {
            if (2*i < Length(params)) {
                Rx(params[2*i], qubits[i]);
            }
            if (2*i+1 < Length(params)) {
                Rz(params[2*i+1], qubits[i]);
            }
        }

        // Entangling layer: CNOT chain
        for (i in 0..n-2) {
            CNOT(qubits[i], qubits[i+1]);
        }
    }

    // Quantum Neural Network forward pass
    operation QNNForward(features : Double[], params : Double[]) : Result {
        use qubits = Qubit[Length(features)];

        // Encode data
        AngleEncoding(features, qubits);

        // Apply variational circuit
        VariationalLayer(params, qubits);

        // Measure expectation (simplified: measure first qubit)
        let result = M(qubits[0]);

        ResetAll(qubits);
        return result;
    }

    // Kernel evaluation: |<0|U†(x)U(y)|0>|²
    operation QuantumKernel(x : Double[], y : Double[]) : Double {
        use qs = Qubit[Length(x)];

        // Prepare U(y)|0⟩
        AngleEncoding(y, qs);

        // Apply U†(x) by reversing angle encoding
        for (i in 0..Length(x)-1) {
            Ry(-x[i], qs[i]);
        }

        // Measure probability of |0...0⟩
        let allZeros = AllZero(qs);
        ResetAll(qs);

        // In practice, run multiple shots and estimate probability
        return allZeros ? 1.0 | 0.0;
    }

    @EntryPoint()
    operation QMLDemo() : Unit {
        let features = [0.5, 0.3];
        let params = [0.1, 0.2, 0.3, 0.4];

        let prediction = QNNForward(features, params);
        Message($"QNN prediction: {prediction}");
    }
}
